    loading: Bool? = nil,
    locale: String? = nil,
    messages: PMChartMessages? = nil,
    mode: PMBarChartMode? = nil,
    onSelect: (@MainActor (PMChartSeriesSelection) -> Void)? = nil,
    orientation: PMBarChartOrientation? = nil,
    series: [PMChartSeries],
    size: PMControlSize? = nil,
