public enum PMConfirmDialogPresentation: String, CaseIterable, Sendable {
  case auto
  case sheet
}

/// `ConfirmDialog.tone`.
public enum PMConfirmDialogTone: String, CaseIterable, Sendable {
  case accent
  case danger
}

/// ConfirmDialog's props (`design/components/confirm-dialog.md`): A Dialog preset for confirming an
/// action. On iOS it is adapted: a confirmation action sheet, or a sheet with the field of a typed
/// phrase.
public struct PMConfirmDialogProps {
  public var cancelLabel: String?
  public var closeLabel: String?
  /// The action's verb; it has no default, so the caller must name the action.
  public var confirmLabel: String
  /// A typed confirmation: the phrase the person types before the confirm enables, such as the name
  /// of the project being deleted. The body draws its field, and focus starts there in both tones.
  public var confirmWith: String?
  /// The phrase field's error while its text cannot become the phrase, `The text does not match` by
  /// default.
  public var confirmWithError: String?
  /// The phrase field's label, `Type {confirmWith} to confirm` by default. Localized hosts pass
  /// their own, with the phrase in it.
  public var confirmWithLabel: String?
  /// Required, because a confirm must say what is at stake.
  public var description: String
  /// A Promise puts the dialog into its pending state until it settles.
  public var onConfirm: @MainActor () -> Void
  public var onOpenChange: (@MainActor (Bool) -> Void)?
  public var open: Bool?
  /// Dialog's `presentation`, passed through (the sheet presentation,
  /// `design/components/README.md`). A confirm is the content-light dialog this option is for.
  /// `'sheet'` keeps the sm card above `30rem` and uses a bottom sheet below it. Footer order,
  /// cancel-first initial focus and the pending lock are the same in both forms.
  public var presentation: PMConfirmDialogPresentation?
  public var title: String
  /// `accent` for consequential but safe actions; the `danger` default is for destructive ones.
  public var tone: PMConfirmDialogTone?
  public var trigger: PMContent?

  public init(
    cancelLabel: String? = nil,
    closeLabel: String? = nil,
    confirmLabel: String,
    confirmWith: String? = nil,
    confirmWithError: String? = nil,
    confirmWithLabel: String? = nil,
    description: String,
    onConfirm: @escaping @MainActor () -> Void,
    onOpenChange: (@MainActor (Bool) -> Void)? = nil,
    open: Bool? = nil,
    presentation: PMConfirmDialogPresentation? = nil,
    title: String,
    tone: PMConfirmDialogTone? = nil,
    trigger: PMContent? = nil
  ) {
    self.cancelLabel = cancelLabel
    self.closeLabel = closeLabel
    self.confirmLabel = confirmLabel
    self.confirmWith = confirmWith
    self.confirmWithError = confirmWithError
    self.confirmWithLabel = confirmWithLabel
    self.description = description
    self.onConfirm = onConfirm
    self.onOpenChange = onOpenChange
    self.open = open
    self.presentation = presentation
    self.title = title
    self.tone = tone
    self.trigger = trigger
  }
}

/// A view that renders ConfirmDialog from its props. The member's file declares `PMConfirmDialog`,
/// which conforms to it.
public protocol PMConfirmDialogRendering: View {
  init(props: PMConfirmDialogProps)
}

