// MARK: - CursorPagination

/// `CursorPagination.mode`.
public enum PMCursorPaginationMode: String, CaseIterable, Sendable {
  case replace
  case append
}

/// CursorPagination's props (`design/components/cursor-pagination.md`): Previous and next controls
/// for a cursor-paged list.
public struct PMCursorPaginationProps {
  /// The app holds the pager while it does something else to the list: every control is disabled
  /// and none shows busy. Not `pending`, which says the pager's own request is in flight.
  public var disabled: Bool?
  public var hasNext: Bool
  /// Whether the list returned a cursor that way; controlled, as cursors belong to the list. The
  /// append form does not read it: it has no previous direction.
  public var hasPrevious: Bool
  public var label: String?
  /// Omit for the generic English defaults; localized hosts pass their own.
  public var messages: PMCursorPaginationMessages?
  /// `replace` (the default) swaps the window for its neighbour, so the list stays bounded.
  /// `append` is "Load more": one action that adds the next window below the ones on screen, for a
  /// feed or a log read from the top.
  public var mode: PMCursorPaginationMode?
  /// The next window: in place of this one, or in the append form below it.
  public var onNext: @MainActor () -> Void
  /// The previous window, in the replace form; the append form has no previous.
  public var onPrevious: (@MainActor () -> Void)?
  /// The requested window has not arrived: the pressed direction shows busy and the other is
  /// disabled, so a slow fetch cannot be followed by a second request.
  public var pending: Bool?
  /// The current window in the app's words, such as "26–50" or "Newest first, page 2"; never a
  /// total, because the list does not return one.
  public var position: String?

  public init(
    disabled: Bool? = nil,
    hasNext: Bool,
    hasPrevious: Bool,
    label: String? = nil,
    messages: PMCursorPaginationMessages? = nil,
    mode: PMCursorPaginationMode? = nil,
    onNext: @escaping @MainActor () -> Void,
    onPrevious: (@MainActor () -> Void)? = nil,
    pending: Bool? = nil,
    position: String? = nil
  ) {
    self.disabled = disabled
    self.hasNext = hasNext
    self.hasPrevious = hasPrevious
    self.label = label
    self.messages = messages
    self.mode = mode
    self.onNext = onNext
    self.onPrevious = onPrevious
    self.pending = pending
    self.position = position
  }
}

/// A view that renders CursorPagination from its props. The member's file declares
/// `PMCursorPagination`, which conforms to it.
public protocol PMCursorPaginationRendering: View {
  init(props: PMCursorPaginationProps)
}

