/// LineChart's props (`design/components/line-chart.md`): A line chart for change over time.
public struct PMLineChartProps {
  /// Annotations from the closed union above: line, band and point, literals only. The frame's
  /// shared annotation layer draws them in `--pm-chart-axis`, with bands washed in
  /// `--pm-chart-other` at 0.08. An annotation never re-centres colour. Colliding labels are
  /// dropped, but the annotation itself always draws because the app asked for it explicitly.
  public var annotations: [PMChartAnnotation]?
  public var baseline: PMChartBaseline?
  /// The line shape. `step` is **`curveStepAfter`**: a measurement holds until the next one.
  /// `'linear'` is engine-internal and not offered here.
  public var curve: PMLineChartCurve?
  /// The data rows. `[]` renders the built-in empty state.
  public var data: [[String: PMChartValue?]]
  /// Key of the series to emphasise. It keeps its slot colour and the rest use `--pm-chart-other`.
  /// A status-toned series keeps its status colour, because reserved meaning is never greyed out.
  public var emphasis: String?
  /// The chart's accessible name. It is required, as for Progress, because an unnamed chart tells a
  /// reader nothing.
  public var label: String
  /// Loading state. On first render the frame shows a quiet `Skeleton`; on refetch it shows the
  /// previous frame at reduced opacity, with no layout jump or flash. Failure is not a chart state:
  /// the app reports errors, and a chart shows only data, never network status.
  public var loading: Bool?
  /// The locale `Intl` formats with. When omitted, the runtime's own resolved locale applies.
  public var locale: String?
  /// Point dots of at least 8px with a 2px surface ring, a second channel for CVD and print.
  public var markers: Bool?
  /// The tier's message catalog. When omitted, the generic English defaults apply. A localized host
  /// passes its own, the same object to every chart on the screen.
  public var messages: PMChartMessages?
  /// Enables the range brush, for a `time` or `linear` x only, because a band has no continuum. The
  /// brush only reports a committed range to app state and never filters the chart itself;
  /// `FilterBar` owns and displays the range. It passes ISO strings for `time` and numbers for
  /// `linear`, and fires on commit only.
  public var onBrushEnd: (@MainActor (PMChartBrushRange) -> Void)?
  /// Called with the row at the reading position, on Enter, Space or click.
  public var onSelect: (@MainActor (PMChartRowSelection) -> Void)?
  /// The series to draw, 1–8. A ninth gets a dev-warning about folding into "Other", never a
  /// generated hue, because the wheel has eight seats.
  public var series: [PMChartSeries]
  /// Frame height, from `--pm-chart-height-*`. The frame never nests a scroll region.
  public var size: PMControlSize?
  /// Syncs the reading position across sibling charts through a module-scope registry, with no
  /// provider. The broadcast is the **x-domain value**, never the row index, and each receiver maps
  /// it through its own scale. Works for a `time` or `linear` x only, like the brush. Escape or
  /// blur clears the whole group.
  public var syncId: String?
  /// Tooltip configuration, on with `'dot'` by default. `false`, for print and report surfaces,
  /// removes only the visual layer.
  public var tooltip: PMChartTooltip?
  /// `area` adds a light wash of the series hue (about 10% alpha) under the line.
  public var variant: PMLineChartVariant?
  public var x: PMChartXAxis
  /// Y axis configuration. The axis renders by default.
  public var y: PMChartYAxis?

  public init(
    annotations: [PMChartAnnotation]? = nil,
    baseline: PMChartBaseline? = nil,
    curve: PMLineChartCurve? = nil,
    data: [[String: PMChartValue?]],
    emphasis: String? = nil,
    label: String,
    loading: Bool? = nil,
    locale: String? = nil,
    markers: Bool? = nil,
    messages: PMChartMessages? = nil,
    onBrushEnd: (@MainActor (PMChartBrushRange) -> Void)? = nil,
    onSelect: (@MainActor (PMChartRowSelection) -> Void)? = nil,
    series: [PMChartSeries],
    size: PMControlSize? = nil,
    syncId: String? = nil,
    tooltip: PMChartTooltip? = nil,
    variant: PMLineChartVariant? = nil,
    x: PMChartXAxis,
    y: PMChartYAxis? = nil
  ) {
    self.annotations = annotations
    self.baseline = baseline
    self.curve = curve
    self.data = data
    self.emphasis = emphasis
    self.label = label
    self.loading = loading
    self.locale = locale
    self.markers = markers
    self.messages = messages
    self.onBrushEnd = onBrushEnd
    self.onSelect = onSelect
    self.series = series
    self.size = size
    self.syncId = syncId
    self.tooltip = tooltip
    self.variant = variant
    self.x = x
    self.y = y
  }
}

