// MARK: - SplitButton

/// SplitButton's lawful variant × tone cells, and only those: the grid the web types as
/// `LawfulVariants`. `lawful` lists them in grid order.
public enum PMSplitButtonAppearance: String, CaseIterable, Sendable {
  case solidAccent = "solid/accent"
  case softAccent = "soft/accent"
  case outlineNeutral = "outline/neutral"
  case outlineAccent = "outline/accent"

  /// Every lawful cell, in grid order.
  public static let lawful: [PMSplitButtonAppearance] = [
    .solidAccent,
    .softAccent,
    .outlineNeutral,
    .outlineAccent
  ]

  /// The cell for a variant and a tone, or `nil` when the grid excludes the pair.
  public init?(variant: PMSplitButtonVariant, tone: PMSplitButtonTone) {
    self.init(rawValue: "\(variant.rawValue)/\(tone.rawValue)")
  }

  public var variant: PMSplitButtonVariant {
    switch self {
    case .solidAccent: .solid
    case .softAccent: .soft
    case .outlineNeutral, .outlineAccent: .outline
    }
  }

  public var tone: PMSplitButtonTone {
    switch self {
    case .solidAccent, .softAccent, .outlineAccent: .accent
    case .outlineNeutral: .neutral
    }
  }
}

/// `SplitButton.variant`. Paired with a tone only through `PMSplitButtonAppearance`.
public enum PMSplitButtonVariant: String, CaseIterable, Sendable {
  case solid
  case soft
  case outline
}

/// `SplitButton.tone`. Paired with a variant only through `PMSplitButtonAppearance`.
public enum PMSplitButtonTone: String, CaseIterable, Sendable {
  case accent
  case neutral
}

/// `SplitButton.presentation`.
public enum PMSplitButtonPresentation: String, CaseIterable, Sendable {
  case auto
  case popover
}

